use anyhow::{anyhow, Result};
use std::sync::mpsc;
use std::thread;
use tiny_http::{Response, Server};

/// Start a local HTTP server on a random port to receive the auth callback.
/// Returns the port and a receiver that will yield the session token.
pub fn start_callback_server(expected_state: &str) -> Result<(u16, mpsc::Receiver<String>)> {
    let server =
        Server::http("127.0.0.1:0").map_err(|e| anyhow!("Failed to start callback server: {e}"))?;

    let port = match server.server_addr().to_ip() {
        Some(addr) => addr.port(),
        None => return Err(anyhow!("Callback server did not bind to an IP address")),
    };

    let (tx, rx) = mpsc::channel();
    let state = expected_state.to_string();

    thread::spawn(move || {
        // Handle requests until we get a valid callback or the server is dropped
        for request in server.incoming_requests() {
            let url = request.url().to_string();

            let params = match url.split_once('?') {
                Some((_, query)) => query,
                None => {
                    let _ = request.respond(
                        Response::from_string("Missing query parameters").with_status_code(400),
                    );
                    continue;
                }
            };

            let mut token = None;
            let mut callback_state = None;

            for pair in params.split('&') {
                if let Some((key, value)) = pair.split_once('=') {
                    match key {
                        "token" => token = Some(value.to_string()),
                        "state" => callback_state = Some(value.to_string()),
                        _ => {}
                    }
                }
            }

            // Verify state parameter
            match callback_state.as_deref() {
                Some(s) if s == state => {}
                _ => {
                    let _ = request.respond(
                        Response::from_string("Invalid state parameter").with_status_code(400),
                    );
                    continue;
                }
            }

            let token = match token {
                Some(t) => t,
                None => {
                    let _ = request
                        .respond(Response::from_string("Missing token").with_status_code(400));
                    continue;
                }
            };

            let html = r#"<html><body style="font-family:system-ui;display:flex;justify-content:center;align-items:center;height:100vh;margin:0"><h2>Authentication successful! You can close this tab.</h2></body></html>"#;
            let response = Response::from_string(html).with_header(
                "Content-Type: text/html"
                    .parse::<tiny_http::Header>()
                    .unwrap(),
            );
            let _ = request.respond(response);

            let _ = tx.send(token);
            break;
        }
    });

    Ok((port, rx))
}

pub const fn server_url() -> &'static str {
    match option_env!("REPLAY_SERVER_URL") {
        Some(url) => url,
        None => "http://localhost:3000",
    }
}

pub(crate) mod config;
mod credentials;
mod server;

use anyhow::{anyhow, Result};
use rand::Rng;
use std::time::Duration;

pub fn login() -> Result<()> {
    let state: String = rand::rng()
        .sample_iter(rand::distr::Alphanumeric)
        .take(32)
        .map(char::from)
        .collect();

    let (port, rx) = server::start_callback_server(&state)?;

    let server_url = config::server_url();
    let login_url =
        format!("{server_url}/login?redirect_uri=http://localhost:{port}/callback&state={state}");

    eprintln!("Opening browser for login...");

    if open::that(&login_url).is_err() {
        eprintln!("Could not open browser. Please visit this URL manually:");
        eprintln!("  {login_url}");
    }

    eprintln!("Waiting for authentication...");

    let token = rx
        .recv_timeout(Duration::from_secs(120))
        .map_err(|_| anyhow!("Login timed out. Please try again."))?;

    credentials::save(&credentials::Credentials { token })?;

    eprintln!("Logged in successfully.");
    Ok(())
}

pub fn logout() -> Result<()> {
    credentials::delete()?;
    eprintln!("Logged out.");
    Ok(())
}

pub fn whoami() -> Result<()> {
    let creds = match credentials::load()? {
        Some(c) => c,
        None => {
            eprintln!("Not logged in. Run `replay login` to authenticate.");
            return Ok(());
        }
    };

    let client = reqwest::blocking::Client::new();
    let resp = client
        .get(format!("{}/api/auth/get-session", config::server_url()))
        .header("Authorization", format!("Bearer {}", creds.token))
        .header("X-Client-Version", env!("CARGO_PKG_VERSION"))
        .send()?;

    if !resp.status().is_success() {
        eprintln!("Session expired or invalid. Run `replay login` to re-authenticate.");
        return Ok(());
    }

    let body: serde_json::Value = resp.json()?;

    if let Some(user) = body.get("user") {
        let name = user
            .get("name")
            .and_then(|v| v.as_str())
            .unwrap_or("unknown");
        let email = user
            .get("email")
            .and_then(|v| v.as_str())
            .unwrap_or("unknown");
        eprintln!("Logged in as {name} ({email})");
    } else {
        eprintln!("Authenticated, but could not read user info.");
    }

    Ok(())
}

/// Load the stored auth token, if any. For use by other modules (e.g. upload).
#[allow(dead_code)]
pub fn get_token() -> Result<Option<String>> {
    Ok(credentials::load()?.map(|c| c.token))
}

/// User info returned by the server.
pub struct UserInfo {
    pub name: String,
    pub email: String,
}

/// Check if the user is logged in and fetch their info.
/// Returns Ok(None) if not logged in or session is invalid.
pub fn get_user_info() -> Result<Option<UserInfo>> {
    let creds = match credentials::load()? {
        Some(c) => c,
        None => return Ok(None),
    };

    let client = reqwest::blocking::Client::new();
    let resp = client
        .get(format!("{}/api/auth/get-session", config::server_url()))
        .header("Authorization", format!("Bearer {}", creds.token))
        .header("X-Client-Version", env!("CARGO_PKG_VERSION"))
        .send()?;

    if !resp.status().is_success() {
        return Ok(None);
    }

    let body: serde_json::Value = resp.json()?;
    if let Some(user) = body.get("user") {
        let name = user
            .get("name")
            .and_then(|v| v.as_str())
            .unwrap_or("unknown")
            .to_string();
        let email = user
            .get("email")
            .and_then(|v| v.as_str())
            .unwrap_or("unknown")
            .to_string();
        Ok(Some(UserInfo { name, email }))
    } else {
        Ok(None)
    }
}

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::fs;
use std::path::PathBuf;

#[derive(Debug, Serialize, Deserialize)]
pub struct Credentials {
    pub token: String,
}

pub fn credentials_path() -> PathBuf {
    dirs::config_dir()
        .unwrap_or_else(|| PathBuf::from("."))
        .join("replay")
        .join("credentials.json")
}

pub fn load() -> Result<Option<Credentials>> {
    let path = credentials_path();
    if !path.exists() {
        return Ok(None);
    }
    let contents =
        fs::read_to_string(&path).with_context(|| format!("Failed to read {}", path.display()))?;
    let creds: Credentials =
        serde_json::from_str(&contents).with_context(|| "Failed to parse credentials")?;
    Ok(Some(creds))
}

pub fn save(creds: &Credentials) -> Result<()> {
    let path = credentials_path();
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)
            .with_context(|| format!("Failed to create {}", parent.display()))?;
    }
    let json = serde_json::to_string_pretty(creds)?;
    fs::write(&path, &json).with_context(|| format!("Failed to write {}", path.display()))?;

    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        fs::set_permissions(&path, fs::Permissions::from_mode(0o600))?;
    }

    Ok(())
}

pub fn delete() -> Result<()> {
    let path = credentials_path();
    if path.exists() {
        fs::remove_file(&path).with_context(|| format!("Failed to remove {}", path.display()))?;
    }
    Ok(())
}

use chrono::{DateTime, Utc};
use serde::Serialize;
use std::path::PathBuf;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Agent {
    Claude,
    Codex,
}

impl std::fmt::Display for Agent {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Agent::Claude => write!(f, "claude"),
            Agent::Codex => write!(f, "codex"),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum Role {
    User,
    Assistant,
}

/// A single content block within a message.
#[derive(Debug, Clone, Serialize)]
#[serde(tag = "type")]
pub enum ContentBlock {
    #[serde(rename = "text")]
    Text { text: String },
    #[serde(rename = "thinking")]
    Thinking { thinking: String },
    #[serde(rename = "tool_use")]
    ToolUse {
        id: String,
        name: String,
        input: serde_json::Value,
    },
    #[serde(rename = "tool_result")]
    ToolResult {
        tool_use_id: String,
        /// Preserved as-is from the API: can be a JSON string or an array of
        /// sub-blocks (text, image, etc.).
        content: serde_json::Value,
        #[serde(default, skip_serializing_if = "std::ops::Not::not")]
        is_error: bool,
    },
    #[serde(rename = "image")]
    Image { source: ImageSource },
}

#[derive(Debug, Clone, Serialize)]
pub struct ImageSource {
    /// e.g. "base64"
    #[serde(rename = "type")]
    pub source_type: String,
    /// e.g. "image/png"
    pub media_type: String,
    /// The base64-encoded image data.
    pub data: String,
}

#[derive(Debug, Clone, Serialize)]
pub struct TokenUsage {
    pub input_tokens: u64,
    pub output_tokens: u64,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub cache_creation_input_tokens: Option<u64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub cache_read_input_tokens: Option<u64>,
}

#[derive(Debug, Clone)]
pub struct Message {
    pub role: Role,
    pub content: Vec<ContentBlock>,
    pub timestamp: DateTime<Utc>,
    /// Model used (assistant messages only).
    pub model: Option<String>,
    /// Why the turn ended (assistant messages only).
    pub stop_reason: Option<String>,
    /// Token usage (assistant messages only).
    pub usage: Option<TokenUsage>,
}

#[derive(Debug, Clone)]
pub struct Session {
    pub id: String,
    pub agent: Agent,
    pub timestamp: DateTime<Utc>,
    pub project_path: Option<String>,
    pub git_branch: Option<String>,
    pub first_user_message: Option<String>,
    pub source_path: PathBuf,
    /// Session title (from custom-title or agent-name).
    pub title: Option<String>,
    /// CLI version that created this session.
    pub cli_version: Option<String>,
    /// Primary model used in this session.
    pub model: Option<String>,
}

#[derive(Debug, Clone)]
pub struct LoadedSession {
    pub session: Session,
    pub messages: Vec<Message>,
}

